def statuts(apps, schema_editor):
    """Année active → active ; les autres : en préparation si elles commencent après l'active, sinon clôturées."""
    Annee = apps.get_model("scolarite", "AnneeScolaire")
    active = Annee.objects.filter(active=True).first()
    for a in Annee.objects.all():
        if a.active:
            a.statut = "active"
        elif active and a.debut > active.debut:
            a.statut = "preparation"
        else:
            a.statut = "cloturee" if active else "preparation"
        a.save(update_fields=["statut"])


